'use strict';
const PLAYER_OUTFITS={default:'Wędrowiec',knight:'Rycerz',scout:'Zwiadowca',desert:'Pustynny wędrowiec'};
const DOG_COATS={brown:['Brązowy','#a67b47'],black:['Czarny','#45433e'],cream:['Kremowy','#dfcba1'],red:['Rudy','#b96c3e']};
const BANNER_COLORS={gold:['Złoty','#d6b55e'],red:['Czerwony','#b65b4c'],blue:['Niebieski','#679cac'],green:['Zielony','#75a16a']};
const BANNER_EMBLEMS={star:'★',moon:'☾',tree:'♣',sword:'⚔'};
function appearance(){state.appearance??={};const a=state.appearance;if(!PLAYER_OUTFITS[a.outfit])a.outfit='default';if(!DOG_COATS[a.dogColor])a.dogColor='brown';if(!BANNER_COLORS[a.bannerColor])a.bannerColor='gold';if(!BANNER_EMBLEMS[a.bannerEmblem])a.bannerEmblem='star';a.dogName=String(a.dogName||'Reksio').trim().slice(0,20)||'Reksio';return a}
function saveAppearance(field,value){const a=appearance(),valid={outfit:PLAYER_OUTFITS,dogColor:DOG_COATS,bannerColor:BANNER_COLORS,bannerEmblem:BANNER_EMBLEMS};if(field==='dogName')value=String(value).trim().slice(0,20)||'Reksio';else if(!valid[field]?.[value])return false;const before=a[field];a[field]=value;if(!save()){a[field]=before;return false}return true}
function dogCoat(){return DOG_COATS[appearance().dogColor][1]}
function drawPlayerAppearance(x,y,force=false,seated=false){const outfit=appearance().outfit;if(outfit==='default'&&!force)return false;const body={default:'#c7a05f',knight:'#a9b4b2',scout:'#6e8b50',desert:'#d8ba7b'}[outfit];if(seated){for(const side of [-1,1])artLine([[x+side*4,y-1],[x+side*10,y+3],[x+side*10,y+10]],'#493e31',5)}else{ctx.fillStyle='#1d302b55';ctx.beginPath();ctx.ellipse(x,y+9,11,5,0,0,7);ctx.fill();drawWalkingLegs(x,y,state.p,'#493e31',5,10)}artRect(x-9,y-15,18,17,body);ctx.fillStyle='#f2d3a1';ctx.beginPath();ctx.arc(x,y-21,7,0,7);ctx.fill();if(outfit==='knight'){artRect(x-8,y-30,16,10,'#c0c9c6');artRect(x-6,y-25,12,3,'#3c4b49');polygon([[x-15,y-13],[x-5,y-13],[x-5,y],[x-10,y+5],[x-15,y]],'#798eaa');artLine([[x+12,y],[x+12,y-29]],'#d7ded5',3)}else if(outfit==='scout'){polygon([[x-10,y-24],[x,y-35],[x+10,y-24]],'#49653d');artLine([[x+11,y-23],[x+16,y-14],[x+11,y-3]],'#ba945f',2);artLine([[x+11,y-23],[x+11,y-3]],'#e6d7b2')}else if(outfit==='desert'){artRect(x-9,y-30,18,7,'#eee0ba');artRect(x-8,y-18,16,4,'#b48555');artRect(x+6,y-24,4,17,'#eee0ba')}else artRect(x-8,y-29,16,5,'#55472f');return true}
function tameCamel(){const s=lifeState();if(!isDesertCampaign()||s.camel||state.food<40||state.playerBoat?.aboard)return false;state.food-=40;s.camel=true;if(!save()){state.food+=40;s.camel=false;return false}return true}
function toggleCamel(){const s=lifeState();if(!isDesertCampaign()||!s.camel||state.playerBoat?.aboard)return false;s.camelMounted=!s.camelMounted;if(s.camelMounted)s.mounted=false;keys={};target=null;save();return true}
function drawCamelPlayer(x,y){ctx.fillStyle='#21382c44';ctx.beginPath();ctx.ellipse(x,y+13,28,8,0,0,7);ctx.fill();artRect(x-22,y-6,42,18,'#b18a52');for(const dx of [-12,4]){ctx.fillStyle='#c5a06a';ctx.beginPath();ctx.arc(x+dx,y-6,10,Math.PI,Math.PI*2);ctx.fill()}const swing=walkingSwing(state.p,x,y);for(const [i,dx] of [-17,-8,8,16].entries())artLine([[x+dx,y+6],[x+dx+swing*(i%2?1:-1),y+24]],'#9a713d',4);artLine([[x+17,y],[x+22,y-25],[x+30,y-28]],'#c5a06a',10);artRect(x+26,y-32,16,10,'#c5a06a');artRect(x+36,y-30,3,3,'#393b2e');artLine([[x-21,y],[x-28,y+8]],'#94703e',3);artRect(x-12,y-9,24,6,'#a14f40');drawPlayerAppearance(x-3,y-17,true,true)}
const outfitCavalry=drawCavalryUnit;drawCavalryUnit=function(u){outfitCavalry(u);if(u.player&&appearance().outfit!=='default')drawPlayerAppearance(u.x-1,u.y-15,true,true)};
const camelTravel=playerTravelMultiplier;playerTravelMultiplier=function(){return camelTravel()*(isDesertCampaign()&&state.life?.camelMounted&&!state.playerBoat?.aboard?1.5:1)};
const camelHorse=togglePlayerHorse;togglePlayerHorse=function(){const result=camelHorse();if(result&&state.life.mounted){state.life.camelMounted=false;save()}return result};
const camelBoat=boardPersonalBoat;boardPersonalBoat=function(){const result=camelBoat();if(result&&state.life){state.life.camelMounted=false;save()}return result};
function renderAppearanceOptions(){const a=appearance(),options=(values,current)=>Object.entries(values).map(([id,label])=>'<option value="'+id+'" '+(id===current?'selected':'')+'>'+ (Array.isArray(label)?label[0]:label)+'</option>').join('');return '<h3>Wygląd</h3><p>Zmiany wyglądu działają od razu i przechodzą do nowych gier.</p><label>Strój <select id="outfitSelect">'+options(PLAYER_OUTFITS,a.outfit)+'</select></label><label>Kolor psa <select id="dogColorSelect">'+options(DOG_COATS,a.dogColor)+'</select></label><label>Imię psa <input id="dogNameInput" maxlength="20" value="'+expansionEscape(a.dogName)+'"></label><button id="saveDogName">Zapisz imię</button><p>Przygarnij psa w panelu „Osada i zwierzęta”, aby zobaczyć jego wygląd.</p><label>Kolor sztandaru <select id="bannerColorSelect">'+options(BANNER_COLORS,a.bannerColor)+'</select></label><label>Herb <select id="bannerEmblemSelect">'+options(BANNER_EMBLEMS,a.bannerEmblem)+'</select></label><h3>Wielbłąd</h3><p>Na pustyni: oswojenie kosztuje 40 żywności. Jazda przyspiesza ruch o 50%. Nie wymaga stajni.</p><button id="camelTame" '+(!isDesertCampaign()||state.life?.camel||state.food<40||state.playerBoat?.aboard?'disabled':'')+'>'+(state.life?.camel?'✓ Wielbłąd oswojony':'Oswój wielbłąda · 40 żywności')+'</button><button id="camelRide" '+(!isDesertCampaign()||!state.life?.camel||state.playerBoat?.aboard?'disabled':'')+'>'+(state.life?.camelMounted?'Zsiądź z wielbłąda':'Wsiądź na wielbłąda')+'</button>'}
const appearanceShop=renderStarterShop;renderStarterShop=function(){appearanceShop();const box=document.createElement('div');box.id='appearanceOptions';box.innerHTML=renderAppearanceOptions();$('starterShop').append(box);for(const [id,field] of [['outfitSelect','outfit'],['dogColorSelect','dogColor'],['bannerColorSelect','bannerColor'],['bannerEmblemSelect','bannerEmblem']])$(id).onchange=e=>saveAppearance(field,e.target.value);$('saveDogName').onclick=()=>{saveAppearance('dogName',$('dogNameInput').value);$('dogNameInput').value=appearance().dogName};$('camelTame').onclick=()=>{if(tameCamel())renderStarterShop()};$('camelRide').onclick=()=>{if(toggleCamel())renderStarterShop()}};
appearance();
